    61→// ProcessETH1Block processes logs from the provided eth1 block.
    62→func (s *Service) ProcessETH1Block(ctx context.Context, blkNum *big.Int) error {
    63→	query := ethereum.FilterQuery{
    64→		Addresses: []common.Address{
    65→			s.cfg.depositContractAddr,
    66→		},
    67→		FromBlock: blkNum,
    68→		ToBlock:   blkNum,
    69→	}
    70→	logs, err := s.httpLogger.FilterLogs(ctx, query)
    71→	if err != nil {
    72→		return err
    73→	}
    74→	for i, filterLog := range logs {
    75→		// ignore logs that are not of the required block number
    76→		if filterLog.BlockNumber != blkNum.Uint64() {
    77→			continue
    78→		}
    79→		if err := s.ProcessLog(ctx, &logs[i]); err != nil {
    80→			return errors.Wrap(err, "could not process log")
    81→		}
    82→	}
    83→	if !s.chainStartData.Chainstarted {
    84→		if err := s.processChainStartFromBlockNum(ctx, blkNum); err != nil {
    85→			return err
    86→		}
    87→	}
    88→	return nil
    89→}
    90→
    91→// ProcessLog is the main method which handles the processing of all
    92→// logs from the deposit contract on the eth1 chain.
    93→func (s *Service) ProcessLog(ctx context.Context, depositLog *gethtypes.Log) error {
    94→	s.processingLock.RLock()
    95→	defer s.processingLock.RUnlock()
    96→	// Process logs according to their event signature.
    97→	if depositLog.Topics[0] == depositEventSignature {
    98→		if err := s.ProcessDepositLog(ctx, depositLog); err != nil {
    99→			return errors.Wrap(err, "Could not process deposit log")
   100→		}
   101→		if s.lastReceivedMerkleIndex%eth1DataSavingInterval == 0 {
   102→			return s.savePowchainData(ctx)
   103→		}
   104→		return nil
   105→	}
   106→	log.WithField("signature", fmt.Sprintf("%#x", depositLog.Topics[0])).Debug("Not a valid event signature")
   107→	return nil
   108→}
   109→
   110→// ProcessDepositLog processes the log which had been received from
   111→// the eth1 chain by trying to ascertain which participant deposited
   112→// in the contract.
   113→func (s *Service) ProcessDepositLog(ctx context.Context, depositLog *gethtypes.Log) error {
   114→	pubkey, withdrawalCredentials, amount, signature, merkleTreeIndex, err := contracts.UnpackDepositLogData(depositLog.Data)
   115→	if err != nil {
   116→		return errors.Wrap(err, "Could not unpack log")
   117→	}
   118→	// If we have already seen this Merkle index, skip processing the log.
   119→	// This can happen sometimes when we receive the same log twice from the
   120→	// ETH1.0 network, and prevents us from updating our trie
   121→	// with the same log twice, causing an inconsistent state root.
   122→	index := int64(binary.LittleEndian.Uint64(merkleTreeIndex)) // lint:ignore uintcast -- MerkleTreeIndex should not exceed int64 in your lifetime.
   123→	if index <= s.lastReceivedMerkleIndex {
   124→		return nil
   125→	}
   126→
   127→	if index != s.lastReceivedMerkleIndex+1 {
   128→		missedDepositLogsCount.Inc()
   129→		return errors.Errorf("received incorrect merkle index: wanted %d but got %d", s.lastReceivedMerkleIndex+1, index)
   130→	}
   131→	s.lastReceivedMerkleIndex = index
   132→
   133→	// We then decode the deposit input in order to create a deposit object
   134→	// we can store in our persistent DB.
   135→	depositData := &ethpb.Deposit_Data{
   136→		Amount:                bytesutil.FromBytes8(amount),
   137→		PublicKey:             pubkey,
   138→		Signature:             signature,
   139→		WithdrawalCredentials: withdrawalCredentials,
   140→	}
   141→
   142→	depositHash, err := depositData.HashTreeRoot()
   143→	if err != nil {
   144→		return errors.Wrap(err, "unable to determine hashed value of deposit")
   145→	}
   146→	// Defensive check to validate incoming index.
   147→	if s.depositTrie.NumOfItems() != int(index) {
   148→		return errors.Errorf("invalid deposit index received: wanted %d but got %d", s.depositTrie.NumOfItems(), index)
   149→	}
   150→	if err = s.depositTrie.Insert(depositHash[:], int(index)); err != nil {
   151→		return err
   152→	}
   153→	deposit := &ethpb.Deposit{
   154→		Data: depositData,
   155→	}
   156→	// Only generate the proofs during pre-genesis.
   157→	if !s.chainStartData.Chainstarted {
   158→		proof, err := s.depositTrie.MerkleProof(int(index))
   159→		if err != nil {
   160→			return errors.Wrap(err, "unable to generate merkle proof for deposit")
   161→		}
   162→		deposit.Proof = proof
   163→	}
   164→
   165→	// We always store all historical deposits in the DB.
   166→	root, err := s.depositTrie.HashTreeRoot()
   167→	if err != nil {
   168→		return errors.Wrap(err, "unable to determine root of deposit trie")
   169→	}
   170→	err = s.cfg.depositCache.InsertDeposit(ctx, deposit, depositLog.BlockNumber, index, root)
   171→	if err != nil {
   172→		return errors.Wrap(err, "unable to insert deposit into cache")
   173→	}
   174→	validData := true
   175→	if !s.chainStartData.Chainstarted {
   176→		s.chainStartData.ChainstartDeposits = append(s.chainStartData.ChainstartDeposits, deposit)
   177→		root, err := s.depositTrie.HashTreeRoot()
   178→		if err != nil {
   179→			return errors.Wrap(err, "unable to determine root of deposit trie")
   180→		}
   181→		eth1Data := &ethpb.Eth1Data{
   182→			DepositRoot:  root[:],
   183→			DepositCount: uint64(len(s.chainStartData.ChainstartDeposits)),
   184→		}
   185→		if err := s.processDeposit(ctx, eth1Data, deposit); err != nil {
   186→			log.WithError(err).Error("Invalid deposit processed")
   187→			validData = false
   188→		}
   189→	} else {
   190→		root, err := s.depositTrie.HashTreeRoot()
   191→		if err != nil {
   192→			return errors.Wrap(err, "unable to determine root of deposit trie")
   193→		}
   194→		s.cfg.depositCache.InsertPendingDeposit(ctx, deposit, depositLog.BlockNumber, index, root)
   195→	}
   196→	if validData {
   197→		// Log the deposit received periodically
   198→		if index%depositLoggingInterval == 0 {
   199→			log.WithFields(logrus.Fields{
   200→				"eth1Block":       depositLog.BlockNumber,
   201→				"publicKey":       fmt.Sprintf("%#x", depositData.PublicKey),
   202→				"merkleTreeIndex": index,
   203→			}).Debug("Deposit registered from deposit contract")
   204→		}
   205→		validDepositsCount.Inc()
   206→		// Notify users what is going on, from time to time.
   207→		if !s.chainStartData.Chainstarted {
   208→			deposits := len(s.chainStartData.ChainstartDeposits)
   209→			if deposits%depositLoggingInterval == 0 {
   210→				valCount, err := helpers.ActiveValidatorCount(ctx, s.preGenesisState, 0)
   211→				if err != nil {
   212→					log.WithError(err).Error("Could not determine active validator count from pre genesis state")
   213→				}
   214→				log.WithFields(logrus.Fields{
   215→					"deposits":          deposits,
   216→					"genesisValidators": valCount,
   217→				}).Info("Processing deposits from Ethereum 1 chain")
   218→			}
   219→		}
   220→	} else {
   221→		log.WithFields(logrus.Fields{
   222→			"eth1Block":       depositLog.BlockHash.Hex(),
   223→			"eth1Tx":          depositLog.TxHash.Hex(),
   224→			"merkleTreeIndex": index,
   225→		}).Info("Invalid deposit registered in deposit contract")
   226→	}
   227→	// We finalize the trie here so that old deposits are not kept around, as they make
   228→	// deposit tree htr computation expensive.
   229→	dTrie, ok := s.depositTrie.(*depositsnapshot.DepositTree)
   230→	if !ok {
   231→		return errors.Errorf("wrong trie type initialized: %T", dTrie)
   232→	}
   233→	if err := dTrie.Finalize(index, depositLog.BlockHash, depositLog.BlockNumber); err != nil {
   234→		log.WithError(err).Error("Could not finalize trie")
   235→	}
   236→
   237→	return nil
   238→}
   239→
   240→// ProcessChainStart processes the log which had been received from
   241→// the eth1 chain by trying to determine when to start the beacon chain.
   242→func (s *Service) ProcessChainStart(genesisTime uint64, eth1BlockHash [32]byte, blockNumber *big.Int) {
   243→	s.chainStartData.Chainstarted = true
   244→	s.chainStartData.GenesisBlock = blockNumber.Uint64()
   245→
   246→	chainStartTime := time.Unix(int64(genesisTime), 0) // lint:ignore uintcast -- Genesis time won't exceed int64 in your lifetime.
   247→
   248→	for i := range s.chainStartData.ChainstartDeposits {
   249→		proof, err := s.depositTrie.MerkleProof(i)
   250→		if err != nil {
   251→			log.WithError(err).Error("Unable to generate deposit proof")
   252→		}
   253→		s.chainStartData.ChainstartDeposits[i].Proof = proof
   254→	}
   255→
   256→	root, err := s.depositTrie.HashTreeRoot()
   257→	if err != nil { // This should never happen.
   258→		log.WithError(err).Error("Unable to determine root of deposit trie, aborting chain start")
   259→		return
   260→	}
   261→	s.chainStartData.Eth1Data = &ethpb.Eth1Data{
   262→		DepositCount: uint64(len(s.chainStartData.ChainstartDeposits)),
   263→		DepositRoot:  root[:],
   264→		BlockHash:    eth1BlockHash[:],
   265→	}
   266→
   267→	log.WithFields(logrus.Fields{
   268→		"chainStartTime": chainStartTime,
   269→	}).Info("Minimum number of validators reached for beacon-chain to start")
   270→	s.cfg.stateNotifier.StateFeed().Send(&feed.Event{
   271→		Type: statefeed.ChainStarted,
   272→		Data: &statefeed.ChainStartedData{
   273→			StartTime: chainStartTime,
   274→		},
   275→	})
   276→	if err := s.savePowchainData(s.ctx); err != nil {
   277→		// continue on if the save fails as this will get re-saved
   278→		// in the next interval.
   279→		log.Error(err)
   280→	}
   281→}
   282→
   283→// createGenesisTime adds in the genesis delay to the eth1 block time
   284→// on which it was triggered.
   285→func createGenesisTime(timeStamp uint64) uint64 {
   286→	return timeStamp + params.BeaconConfig().GenesisDelay
   287→}
   288→
   289→// processPastLogs processes all the past logs from the deposit contract and
   290→// updates the deposit trie with the data from each individual log.
   291→func (s *Service) processPastLogs(ctx context.Context) error {
   292→	currentBlockNum := s.latestEth1Data.LastRequestedBlock
   293→	deploymentBlock := params.BeaconNetworkConfig().ContractDeploymentBlock
   294→	// Start from the deployment block if our last requested block
   295→	// is behind it. This is as the deposit logs can only start from the
   296→	// block of the deployment of the deposit contract.
   297→	currentBlockNum = max(currentBlockNum, deploymentBlock)
   298→	// To store all blocks.
   299→	headersMap := make(map[uint64]*types.HeaderInfo)
   300→	rawLogCount, err := s.depositContractCaller.GetDepositCount(&bind.CallOpts{})
   301→	if err != nil {
   302→		return err
   303→	}
   304→	logCount := binary.LittleEndian.Uint64(rawLogCount)
   305→
   306→	latestFollowHeight, err := s.followedBlockHeight(ctx)
   307→	if err != nil {
   308→		return err
   309→	}
   310→
   311→	batchSize := s.cfg.eth1HeaderReqLimit
   312→	additiveFactor := uint64(float64(batchSize) * additiveFactorMultiplier)
   313→
   314→	log.WithFields(logrus.Fields{
   315→		"currentEth1Block": latestFollowHeight,
   316→		"currentLogCount":  logCount,
   317→	}).Debug("Processing historical deposit logs")
   318→
   319→	for currentBlockNum < latestFollowHeight {
   320→		currentBlockNum, batchSize, err = s.processBlockInBatch(ctx, currentBlockNum, latestFollowHeight, batchSize, additiveFactor, logCount, headersMap)
   321→		if err != nil {
   322→			return err
   323→		}
   324→	}
   325→
   326→	s.latestEth1DataLock.Lock()
   327→	s.latestEth1Data.LastRequestedBlock = currentBlockNum
   328→	s.latestEth1DataLock.Unlock()
   329→
   330→	c, err := s.cfg.beaconDB.FinalizedCheckpoint(ctx)
   331→	if err != nil {
   332→		return err
   333→	}
   334→	fRoot := bytesutil.ToBytes32(c.Root)
   335→	// Return if no checkpoint exists yet.
   336→	if fRoot == params.BeaconConfig().ZeroHash {
   337→		return nil
   338→	}
   339→	fState := s.cfg.finalizedStateAtStartup
   340→	isNil := fState == nil || fState.IsNil()
   341→
   342→	// If processing past logs take a long time, we
   343→	// need to check if this is the correct finalized
   344→	// state we are referring to and whether our cached
   345→	// finalized state is referring to our current finalized checkpoint.
   346→	// The current code does ignore an edge case where the finalized
   347→	// block is in a different epoch from the checkpoint's epoch.
   348→	// This only happens in skipped slots, so pruning it is not an issue.
   349→	if isNil || slots.ToEpoch(fState.Slot()) != c.Epoch {
   350→		fState, err = s.cfg.stateGen.StateByRoot(ctx, fRoot)
   351→		if err != nil {
   352→			return err
   353→		}
   354→	}
   355→	if fState != nil && !fState.IsNil() && fState.Eth1DepositIndex() > 0 {
   356→		s.cfg.depositCache.PrunePendingDeposits(ctx, int64(fState.Eth1DepositIndex())) // lint:ignore uintcast -- deposit index should not exceed int64 in your lifetime.
   357→	}
   358→	return nil
   359→}
   360→
   361→func (s *Service) processBlockInBatch(ctx context.Context, currentBlockNum uint64, latestFollowHeight uint64, batchSize uint64, additiveFactor uint64, logCount uint64, headersMap map[uint64]*types.HeaderInfo) (uint64, uint64, error) {
   362→	// Batch request the desired headers and store them in a
   363→	// map for quick access.
   364→	requestHeaders := func(startBlk uint64, endBlk uint64) error {
   365→		headers, err := s.batchRequestHeaders(startBlk, endBlk)
   366→		if err != nil {
   367→			return err
   368→		}
   369→		for _, h := range headers {
   370→			if h != nil && h.Number != nil {
   371→				headersMap[h.Number.Uint64()] = h
   372→			}
   373→		}
   374→		return nil
   375→	}
   376→
   377→	start := currentBlockNum
   378→	end := currentBlockNum + batchSize
   379→	// Appropriately bound the request, as we do not
   380→	// want request blocks beyond the current follow distance.
   381→	end = min(end, latestFollowHeight)
   382→	query := ethereum.FilterQuery{
   383→		Addresses: []common.Address{
   384→			s.cfg.depositContractAddr,
   385→		},
   386→		FromBlock: new(big.Int).SetUint64(start),
   387→		ToBlock:   new(big.Int).SetUint64(end),
   388→	}
   389→	remainingLogs := logCount - uint64(s.lastReceivedMerkleIndex+1)
   390→	// only change the end block if the remaining logs are below the required log limit.
   391→	// reset our query and end block in this case.
   392→	withinLimit := remainingLogs < depositLogRequestLimit
   393→	aboveFollowHeight := end >= latestFollowHeight
   394→	if withinLimit && aboveFollowHeight {
   395→		query.ToBlock = new(big.Int).SetUint64(latestFollowHeight)
   396→		end = latestFollowHeight
   397→	}
   398→	logs, err := s.httpLogger.FilterLogs(ctx, query)
   399→	if err != nil {
   400→		if tooMuchDataRequestedError(err) {
   401→			if batchSize == 0 {
   402→				return 0, 0, errors.New("batch size is zero")
   403→			}
   404→
   405→			// multiplicative decrease
   406→			batchSize /= multiplicativeDecreaseDivisor
   407→			return currentBlockNum, batchSize, nil
   408→		}
   409→		return 0, 0, err
   410→	}
   411→	// Only request headers before chainstart to correctly determine
   412→	// genesis.
   413→	if !s.chainStartData.Chainstarted {
   414→		if err := requestHeaders(start, end); err != nil {
   415→			return 0, 0, err
   416→		}
   417→	}
   418→
   419→	s.latestEth1DataLock.RLock()
   420→	lastReqBlock := s.latestEth1Data.LastRequestedBlock
   421→	s.latestEth1DataLock.RUnlock()
   422→
   423→	for i, filterLog := range logs {
   424→		if filterLog.BlockNumber > currentBlockNum {
   425→			if err := s.checkHeaderRange(ctx, currentBlockNum, filterLog.BlockNumber-1, headersMap, requestHeaders); err != nil {
   426→				return 0, 0, err
   427→			}
   428→			// set new block number after checking for chainstart for previous block.
   429→			s.latestEth1DataLock.Lock()
   430→			s.latestEth1Data.LastRequestedBlock = currentBlockNum
   431→			s.latestEth1DataLock.Unlock()
   432→			currentBlockNum = filterLog.BlockNumber
   433→		}
   434→		if err := s.ProcessLog(ctx, &logs[i]); err != nil {
   435→			// In the event the execution client gives us a garbled/bad log
   436→			// we reset the last requested block to the previous valid block range. This
   437→			// prevents the beacon from advancing processing of logs to another range
   438→			// in the event of an execution client failure.
   439→			s.latestEth1DataLock.Lock()
   440→			s.latestEth1Data.LastRequestedBlock = lastReqBlock
   441→			s.latestEth1DataLock.Unlock()
   442→			return 0, 0, err
   443→		}
   444→	}
   445→	if err := s.checkHeaderRange(ctx, currentBlockNum, end, headersMap, requestHeaders); err != nil {
   446→		return 0, 0, err
   447→	}
   448→	currentBlockNum = end
   449→
   450→	if batchSize < s.cfg.eth1HeaderReqLimit {
   451→		// update the batchSize with additive increase
   452→		batchSize += additiveFactor
   453→		if batchSize > s.cfg.eth1HeaderReqLimit {
   454→			batchSize = s.cfg.eth1HeaderReqLimit
   455→		}
   456→	}
   457→	return currentBlockNum, batchSize, nil
   458→}
   459→
   460→// requestBatchedHeadersAndLogs requests and processes all the headers and
   461→// logs from the period last polled to now.
   462→func (s *Service) requestBatchedHeadersAndLogs(ctx context.Context) error {
   463→	// We request for the nth block behind the current head, in order to have
   464→	// stabilized logs when we retrieve it from the eth1 chain.
   465→
   466→	requestedBlock, err := s.followedBlockHeight(ctx)
   467→	if err != nil {
   468→		return err
   469→	}
   470→	if requestedBlock > s.latestEth1Data.LastRequestedBlock &&
   471→		requestedBlock-s.latestEth1Data.LastRequestedBlock > maxTolerableDifference {
   472→		log.Infof("Falling back to historical headers and logs sync. Current difference is %d", requestedBlock-s.latestEth1Data.LastRequestedBlock)
   473→		return s.processPastLogs(ctx)
   474→	}
   475→	for i := s.latestEth1Data.LastRequestedBlock + 1; i <= requestedBlock; i++ {
   476→		// Cache eth1 block header here.
   477→		_, err := s.BlockHashByHeight(ctx, new(big.Int).SetUint64(i))
   478→		if err != nil {
   479→			return err
   480→		}
   481→		err = s.ProcessETH1Block(ctx, new(big.Int).SetUint64(i))
   482→		if err != nil {
   483→			return err
   484→		}
   485→		s.latestEth1DataLock.Lock()
   486→		s.latestEth1Data.LastRequestedBlock = i
   487→		s.latestEth1DataLock.Unlock()
   488→	}
   489→
   490→	return nil
   491→}
   492→
   493→func (s *Service) retrieveBlockHashAndTime(ctx context.Context, blkNum *big.Int) ([32]byte, uint64, error) {
   494→	bHash, err := s.BlockHashByHeight(ctx, blkNum)
   495→	if err != nil {
   496→		return [32]byte{}, 0, errors.Wrap(err, "could not get eth1 block hash")
   497→	}
   498→	if bHash == [32]byte{} {
   499→		return [32]byte{}, 0, errors.Wrap(err, "got empty block hash")
   500→	}
   501→	timeStamp, err := s.BlockTimeByHeight(ctx, blkNum)
   502→	if err != nil {
   503→		return [32]byte{}, 0, errors.Wrap(err, "could not get block timestamp")
   504→	}
   505→	return bHash, timeStamp, nil
   506→}
   507→
   508→func (s *Service) processChainStartFromBlockNum(ctx context.Context, blkNum *big.Int) error {
   509→	bHash, timeStamp, err := s.retrieveBlockHashAndTime(ctx, blkNum)
   510→	if err != nil {
   511→		return err
   512→	}
   513→	s.processChainStartIfReady(ctx, bHash, blkNum, timeStamp)
   514→	return nil
   515→}
   516→
   517→func (s *Service) processChainStartFromHeader(ctx context.Context, header *types.HeaderInfo) {
   518→	s.processChainStartIfReady(ctx, header.Hash, header.Number, header.Time)
   519→}
   520→
   521→func (s *Service) checkHeaderRange(ctx context.Context, start, end uint64, headersMap map[uint64]*types.HeaderInfo,
   522→	requestHeaders func(uint64, uint64) error) error {
   523→	for i := start; i <= end; i++ {
   524→		if !s.chainStartData.Chainstarted {
   525→			h, ok := headersMap[i]
   526→			if !ok {
   527→				if err := requestHeaders(i, end); err != nil {
   528→					return err
   529→				}
   530→				// Retry this block.
   531→				i--
   532→				continue
   533→			}
   534→			s.processChainStartFromHeader(ctx, h)
   535→		}
   536→	}
   537→	return nil
   538→}
   539→
   540→// retrieves the current active validator count and genesis time from
   541→// the provided block time.
   542→func (s *Service) currentCountAndTime(ctx context.Context, blockTime uint64) (uint64, uint64) {
   543→	if s.preGenesisState.NumValidators() == 0 {
   544→		return 0, 0
   545→	}
   546→	valCount, err := helpers.ActiveValidatorCount(ctx, s.preGenesisState, 0)
   547→	if err != nil {
   548→		log.WithError(err).Error("Could not determine active validator count from pre genesis state")
   549→		return 0, 0
   550→	}
   551→	return valCount, createGenesisTime(blockTime)
   552→}
   553→
   554→func (s *Service) processChainStartIfReady(ctx context.Context, blockHash [32]byte, blockNumber *big.Int, blockTime uint64) {
   555→	valCount, genesisTime := s.currentCountAndTime(ctx, blockTime)
   556→	if valCount == 0 {
   557→		return
   558→	}
   559→	triggered := coreState.IsValidGenesisState(valCount, genesisTime)
   560→	if triggered {
   561→		s.chainStartData.GenesisTime = genesisTime
   562→		s.ProcessChainStart(s.chainStartData.GenesisTime, blockHash, blockNumber)
   563→	}
   564→}
   565→
   566→// savePowchainData saves all powchain related metadata to disk.
   567→func (s *Service) savePowchainData(ctx context.Context) error {
   568→	pbState, err := statenative.ProtobufBeaconStatePhase0(s.preGenesisState.ToProtoUnsafe())
   569→	if err != nil {
   570→		return err
   571→	}
   572→	eth1Data := &ethpb.ETH1ChainData{
   573→		CurrentEth1Data:   s.latestEth1Data,
   574→		ChainstartData:    s.chainStartData,
   575→		BeaconState:       pbState, // I promise not to mutate it!
   576→		DepositContainers: s.cfg.depositCache.AllDepositContainers(ctx),
   577→	}
   578→	fd, err := s.cfg.depositCache.FinalizedDeposits(ctx)
   579→	if err != nil {
   580→		return errors.Errorf("could not get finalized deposit tree: %v", err)
   581→	}
   582→	tree, ok := fd.Deposits().(*depositsnapshot.DepositTree)
   583→	if !ok {
   584→		return errors.New("deposit tree was not EIP4881 DepositTree")
   585→	}
   586→	eth1Data.DepositSnapshot, err = tree.ToProto()
   587→	if err != nil {
   588→		return err
   589→	}
   590→	return s.cfg.beaconDB.SaveExecutionChainData(ctx, eth1Data)
   591→}
   592→

